ORDER BY ( SELECT MIN(cp.amount_units) FROM channel_prices cp JOIN product_variants pv ON pv.id = cp.variant_id WHERE pv.product_id = p.id AND pv.listing_status = 'ACTIVE' AND cp.channel = #{channel}::sales_channel AND cp.status = 'ACTIVE' AND cp.effective_from <= NOW() AND (cp.effective_to IS NULL OR cp.effective_to > NOW()) ) DESC
ORDER BY p.created_at DESC
